import type {ForwardedRef} from 'react';
import React, {forwardRef, useEffect} from 'react';
import {useOnyx} from 'react-native-onyx';
import NewPicker from '@components/NewPicker';
import useLocalize from '@hooks/useLocalize';
import ONYXKEYS from '@src/ONYXKEYS';

const propTypes = {
    /** Currently selected value */
    value: PropTypes.string,

    /** Function to call when the user selects a value */
    onInputChange: PropTypes.func.isRequired,
};

const defaultProps = {
    value: '',
};

function DefaultValuePicker({value = '', onInputChange}: InitialListValueSelectorProps, ref: ForwardedRef<View>) {
    const {translate} = useLocalize();
    const [formDraft] = useOnyx(ONYXKEYS.FORMS.WORKSPACE_REPORT_FIELDS_FORM_DRAFT);

    const listValues = Object.values(formDraft?.listValues ?? {});
    const disabledOptions = Object.values(formDraft?.disabledListValues ?? {});

    const items = listValues.map((listValue, index) => ({
        value: listValue,
        label: listValue,
        enabled: !disabledOptions[index],
    }));

    useEffect(() => {
        const currentValueIndex = listValues.findIndex((listValue) => listValue === value);
        const isCurrentValueDisabled = disabledOptions[currentValueIndex] ?? true;

        if (isCurrentValueDisabled && value !== '') {
            onInputChange?.('');
        }
    }, [disabledOptions, listValues, onInputChange, value]);

    return (
        <NewPicker
            ref={ref}
            label={translate('common.initialValue')}
            items={items}
            onInputChange={(inputValue) => onInputChange(value === inputValue ? '' : inputValue)}
            value={value}
        />
    );
}

