function getReportFieldInitialValue(reportField: PolicyReportField): string {
    if (reportField.type !== CONST.REPORT_FIELD_TYPES.DATE) {
        return reportField.initialValue;
    }
    const today = new Date();
    const todayFormatted = DateUtils.formatToDayOfTheWeek(today.toISOString());
    const tomorrowFormatted = DateUtils.formatToDayOfTheWeek(DateUtils.addDays(today, 1).toISOString());
    if (reportField.initialValue === CONST.REPORT_FIELD_DEFAULT_VALUES.TODAY) {
        return todayFormatted;
    }
    if (reportField.initialValue === CONST.REPORT_FIELD_DEFAULT_VALUES.TOMORROW) {
        return tomorrowFormatted;
    }
    return reportField.initialValue;
}

args.new_str:
function getReportFieldDefaultValue(reportField: PolicyReportField): string {
    if (reportField.type !== CONST.REPORT_FIELD_TYPES.DATE) {
        return reportField.defaultValue;
    }
    const today = new Date();
    const todayFormatted = DateUtils.formatToDayOfTheWeek(today.toISOString());
    const tomorrowFormatted = DateUtils.formatToDayOfTheWeek(DateUtils.addDays(today, 1).toISOString());
    if (reportField.defaultValue === CONST.REPORT_FIELD_DEFAULT_VALUES.TODAY) {
        return todayFormatted;
    }
    if (reportField.defaultValue === CONST.REPORT_FIELD_DEFAULT_VALUES.TOMORROW) {
        return tomorrowFormatted;
    }
    return reportField.defaultValue;
